INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(30301, 'Song of Songs 8:5', 'Song of Songs', 8, 5, 'دا د صحرا نه څوک راروان دے نه، چې خپل سر يې د محبوبې په اوږه باندې اېښے دېنه؟ محبوبه زۀ تا د سيب د ونې لاندې راپاڅومه، په کوم ځائ کښې چې تۀ خپلې مور زيږولے ينه، چرته کښې چې په ډېر تکليف هغې تۀ زيږولے ينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30302, 'Song of Songs 8:6', 'Song of Songs', 8, 6, 'زما مينه په خپل زړۀ باندې لکه د مهر په شان ولګوه نه، او په خپل لاس باندې ما لکه د مهر په شان ولګوه نه. ځکه چې مينه لکه د مرګ په شان زورَوره ده نه، او د هغۀ غېرت تر عالمِ ارواح پورې رسيږينه، او د مينې د اور شُغلې ډيرې زورَورې دينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30303, 'Song of Songs 8:7', 'Song of Songs', 8, 7, 'ډيرې اوبۀ د مينې اور مړ کولے نۀ شينه، او نۀ سېلاب دا وړلے شينه. کۀ څوک غواړى چې په خپل ټول مال دولت سره مينه په بيعه واخلينه خو د هغۀ قيمت به د مينې په مقابل کښې حقير وشمېرلے شينه. دوستان', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30304, 'Song of Songs 8:8', 'Song of Songs', 8, 8, 'زمونږ يوه وړه خور ده نه، او لا تر اوسه د هغې سينې شوې نۀ دينه. کۀ څوک د هغې غوښتلو له را شينه نو مونږ به څۀ کوُو نه؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30305, 'Song of Songs 8:9', 'Song of Songs', 8, 9, 'کۀ هغه لکه د يو دېوال په شان پېغله وے نه، نو مونږ به د هغې د سپينو زرو د برج سره حفاظت کړے ونه. او کۀ هغه يوه دروازه وے نه، نو مونږ به ورته د دِيار تختې لګولے وے نه. محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30306, 'Song of Songs 8:10', 'Song of Songs', 8, 10, 'زۀ د يو دېوال په شان پېغله ومه، او اوس زما سينې لکه د برجونه په شان دينه. کله چې زما جانان ما ته ګورينه، نو هغه زما په کتلو باندې خوشحاليږينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30307, 'Song of Songs 8:11', 'Song of Songs', 8, 11, 'د سليمان په بعل هامون کښې د انګورو يو باغ وونه، کوم چې هغۀ ماليانو ته په اجاره ورکړے وونه، هر يو به ورله زر د سپينو زرو سيکې ورکولے نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30308, 'Song of Songs 8:12', 'Song of Songs', 8, 12, 'خو زما د انګورو باغ زما دے چې چا له يې ورکومه، سليمانه، ما له د سپينو زرو زر سيکې مۀ راکوه نه، خو زۀ به هغه چا ته د سپينو زرو دوه سوه سيکې ورکړمه، څوک چې زما د باغ د مېوو خيال ساتينه. محبوب', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30309, 'Song of Songs 8:13', 'Song of Songs', 8, 13, 'زما محبوبې، تۀ چې په باغ کښې ژوند کوينه، زما دوستان په دې انتظار کښې دينه چې ستا آواز واورينه. خو پرېږده چې زۀ واورمه محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30310, 'Song of Songs 8:14', 'Song of Songs', 8, 14, 'زما جانانه، زر په منډه راشه، او يا لکه د هوسۍ او د ځوان غرڅۀ په شان راشه خوشبوداره غونډو ته راشه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30311, '2 Samuel 17:28', '2 Samuel', 17, 28, 'هغوی بسترې، کاسې او خاورین لوښي راوړل. همدارنګه هغوی غنم، اوربشې، اوړه، وریتې شوې غلې دانې، دال، لوبیا،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30312, '2 Samuel 17:29', '2 Samuel', 17, 29, 'شات، مستې، د غواګانو د شیدو پنیر او پسونه هم د داود او د هغه د خلکو دپاره راوړل چې ویې خوري. ځکه چې هغوی ویل: «خلک به په دښته کې وږي، تږي او ستړي شوي وي.»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30313, 'Song of Songs 5:1', 'Song of Songs', 5, 1, 'زما دُنيا، زما ناوې، زۀ په خپل باغ کښې داخل شوے يمه. زۀ د مُر چيړ او خوشبوداره مصالحې راټولومه. ما خپل ګبين د شاتو سره وخوړلونه، او زۀ خپل پئ او مے څښمه. ښځې اے عاشقانو، وخورئ او وڅښئينه. او د مينې نه مست شئينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30314, 'Song of Songs 5:2', 'Song of Songs', 5, 2, 'زۀ اودۀ ومه خو زما زړۀ بېدار وونه، غوږ شه. زما جانان ور ټکوينه. ”زما د زړۀ دُنيا او محبوبې ور کولاو کړه، زما ګوګوشتکې، زما بې‌عېبه مينې. محبوب زما سر په شبنم باندې لوند دېنه، او د شپې پرخې مې وېښتۀ لوندۀ کړى دينه.“ محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30315, 'Song of Songs 5:3', 'Song of Songs', 5, 3, 'ما خو جامې ويستلې دينه، نو دا بيا دوباره واچوم څۀ؟ ما خپلې پښې وينځلې دينه، بيا دا دوباره په خاورو ګنده کړم څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30316, 'Song of Songs 5:4', 'Song of Songs', 5, 4, 'زما جانان خپل لاس په ور کښې راوږد کړونه، نو زما زړۀ د هغۀ دپاره په درزېدو شونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30317, 'Song of Songs 5:5', 'Song of Songs', 5, 5, 'نو زۀ راپاڅېدم چې خپل جانان ته ور کولاو کړمه. زما د لاسونو نه عطر په څڅېدو شونه. زما د ګوتو نه د مُر چيړ په څڅېدو شونه کله چې ما د ور کُنډه راښکله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30318, 'Song of Songs 5:6', 'Song of Songs', 5, 6, 'ما خپل جانان ته ور کولاو کړونه، خو هغه بيا تلے وو، نو زۀ سخته پرېشانه شومه، ما هغه ولټولو، خو هغه مې پېدا نۀ کړونه، ما هغۀ ته آواز وکړونه، خو هغۀ ما ته جواب رانۀ کړونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30319, 'Song of Songs 5:7', 'Song of Songs', 5, 7, 'کومو څوکيدارانو چې په ښار کښې ګشت کولونه نو هغوئ زۀ ونيولم، هغوئ زۀ ووهلمه او په وهلو يې تکه شنه کړمه، او د ښار د دېوالونو چوکيدارانو زما د مخ نه پلو اوچت کړونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30320, 'Song of Songs 5:8', 'Song of Songs', 5, 8, 'اے د يروشلم ښځو، ما سره دا وعده وکړئينه، کۀ چرې تاسو زما جانان وليدلو، هغۀ ته ووائينه چې زۀ د هغۀ د مينې په وجه کمزورې شوې يمه. ښځې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30321, 'Song of Songs 5:9', 'Song of Songs', 5, 9, 'اے په ټولو پېغلو کښې ښائسته جينۍ، ستا جانان د نورو سړو نه کوم خاص خصوصيت لرينه؟ په هغۀ کښې داسې څۀ خاص دينه، چې مونږ تا سره دا لوظ وکړونه؟ محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30322, 'Song of Songs 5:10', 'Song of Songs', 5, 10, 'زما جانان سور سپين دېنه، او په لسو زرو کښې د ټولو نه اعلىٰ دېنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30323, 'Song of Songs 5:11', 'Song of Songs', 5, 11, 'د هغۀ سر د سوچه سرو زرو دېنه، د هغۀ وېښتۀ وَل وَل دينه، او لکه د کارغۀ په شان تور دېنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30324, 'Song of Songs 5:12', 'Song of Songs', 5, 12, 'د هغۀ سترګې د ګوګوشتکو په شان دينه چې د اوبو د چينو په خوا کښې وينه سپينې ګوګوشتکې لکه د پئيو په شان چې د تالاب په خوا کښې ناستې وينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30325, 'Song of Songs 5:13', 'Song of Songs', 5, 13, 'د هغۀ اننګى د باغ په شان دينه، چې د خوشبودارو بوټو نه ډک وينه. د هغۀ شونډې د لاله د ګل په شان دينه، لکه چې د مُر په چيړ خوشبويه شوې وينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30326, 'Song of Songs 5:14', 'Song of Songs', 5, 14, 'د هغۀ لاسونه د سرو زرو سيخونه دينه، چې په دې کښې قيمتى کاڼى لګېدلى وينه. د هغۀ بدن لکه د هاتى د غاښونو په شان سپين دېنه، او چې په کښې نيلم کاڼى لګېدلى وينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30327, 'Song of Songs 5:15', 'Song of Songs', 5, 15, 'د هغۀ پښې د سنګِ مرمرو د ستنو په شان دينه چې په سرو زرو کښې لګولے شوې وينه. د هغۀ شکل د لبنان د غرونو د خاص دِيار په شان ښکارينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30328, 'Song of Songs 5:16', 'Song of Songs', 5, 16, 'هغه ډېره خوږه خولۀ لرينه، هغه په هر لحاظ زړۀ راښکونکے دېنه، نو، اے د يروشلم ښځو، زما جانان او زما آشنا دغه شان دېنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30329, 'Genesis 41:45', 'Genesis', 41, 45, 'فرعون په یوسف باندې صفنات فعنیح نوم کېښود او د اون د کاهن فوطي‌فارع لور اسنات یې هغه ته په نکاح ورکړه. نو په دې ډول یوسف د مصر په ټول هېواد باندې واک تر‌لاسه کړ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30330, 'Genesis 41:46', 'Genesis', 41, 46, 'یوسف دېرش کلن ؤ چې د مصر د پاچا یعنې فرعون په خدمت کولو یې پیل وکړ. یوسف د فرعون د حضور څخه لاړ او په ټول مصر کې وګرځېد.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30331, 'Song of Songs 2:1', 'Song of Songs', 2, 1, 'زۀ لکه د شارون د ګلاب په شان يمه، او په پټو کښې د لاله د ګل په شان يمه. محبوب', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30332, 'Song of Songs 2:2', 'Song of Songs', 2, 2, 'لکه چې په ازغو کښې د لاله ګل وينه، زما محبوبه د پېغلو په مينځ کښې داسې وينه. محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30333, 'Song of Songs 2:3', 'Song of Songs', 2, 3, 'لکه د سيب د ونې په شان په ځنګل کښې زما جانان د نورو زلمو په مينځ کښې دېنه. د هغۀ د سورى لاندې په کښېناستو ډېره خوشحالېږمه، او زما په خولۀ د هغۀ مېوې خوږې لګيږينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30334, 'Song of Songs 2:4', 'Song of Songs', 2, 4, 'هغۀ زۀ د خپل ځان سره د مېلمنو هال ته روانه کړمه، او زۀ يې په خپله مينه کښې ونغښتلمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30335, 'Song of Songs 2:5', 'Song of Songs', 2, 5, 'د کشمشو سره يې ما ته طاقت راکړلو، او د سيوانو سره يې زۀ تازه کړمه، ځکه د مينې په وجه مړاوې شوې ومه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30336, 'Song of Songs 2:6', 'Song of Songs', 2, 6, 'د هغۀ ګس لاس زما د سر لاندې وونه، او د هغۀ ښى لاس ځانته راغاړه ايستمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30337, 'Song of Songs 2:7', 'Song of Songs', 2, 7, 'اے د يروشلم جينکو، ما سره ټينګه وعده وکړئ، ترڅو چې مونږ پراتۀ يونه مونږ به نۀ په عذابوئينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30338, 'Song of Songs 2:8', 'Song of Songs', 2, 8, 'وګوره، چې جانان مې راروان دېنه، هغه په غرونو راخېژينه، او په غونډو ټوپونه وهينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30339, 'Song of Songs 2:9', 'Song of Songs', 2, 9, 'زما جانان لکه هوسۍ او يا د ځوان هوسۍ په شان دېنه، وګوره هغه اوس زمونږ د دېوال شاته ولاړ دېنه، هلته د کړکۍ د جال نه دننه کوټې ته ګورينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30340, 'Song of Songs 2:10', 'Song of Songs', 2, 10, 'زما جانان ما ته ووئيل، محبوب ”زما محبوبې، راپاڅه، ښائسته محبوبې، راځه ما سره لاړه شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30341, 'Song of Songs 2:11', 'Song of Songs', 2, 11, 'وګوره، ژمې تېر شو بارانونه ودرېدل او بس شونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30342, 'Song of Songs 2:12', 'Song of Songs', 2, 12, 'په زمکه ګلونه راښکاره شونه، د سندرو وئيلو موسم رارسېدلے دېنه، زمونږ په مُلک کښې د ګوګوشتکو آوازونه اورېدلے کيږينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30343, 'Song of Songs 2:13', 'Song of Songs', 2, 13, 'د اينځر بوټو خپله وړومبۍ مېوه ونيوله، او د انګورو بوټو د خپلو غوټو خوشبو خوره کړله. راپاڅه، راشه، زما محبوبې، زما ښائسته محبوبې، راځه ما سره لاړه شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30344, 'Song of Songs 2:14', 'Song of Songs', 2, 14, 'زما ګوګوشتکې په کمر کښې د ګټانو شاته خپل ځان پټ کړے دېنه. زۀ ستا مخ ليدل غواړمه، او ستا آواز اورېدل غواړمه. ځکه چې ستا آواز خوږ دېنه، او ستا مخ ښائسته دېنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30345, 'Song of Songs 2:15', 'Song of Songs', 2, 15, 'لومبړې ونيسه، وړې لومبړې ونيسه، هسې نه چې هغوئ د انګورو باغ تباه کړينه، ځکه چې زمونږ د انګور بوټو غوټۍ نيولې دينه.“ محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30346, 'Song of Songs 2:16', 'Song of Songs', 2, 16, 'جانان زما او زۀ د جانان يمه، هغه چې د لاله په ګلونو کښې مزې کوينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30347, 'Song of Songs 2:17', 'Song of Songs', 2, 17, 'د سحر رڼا نه وړاندې زما جانانه، چې شپه په ختمېدو شى، ما نه لاړ شه جانانه، لکه د هوسۍ او يا د تکړه هوسۍ په شان په کاڼيزه غرونو باندې ما نه په ټوپونو او مستۍ سره لاړ شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30348, 'Genesis 23:10', 'Genesis', 23, 10, 'عفرون په خپله د نورو حیتیانو سره د ښار په دروازه کې د غونډې په ځای کې ناست ؤ. هغه ابراهیم ته د ټولو حیتیانو په مخکې چې هلته حاضر وو ځواب ورکړ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30349, 'Genesis 23:11', 'Genesis', 23, 11, 'هغه وویل: «نه، زما باداره! زما خبره واوره. زه دا پټی او هغه سمڅه چې په هغه کې ده د خپل قوم په مخکې تاته درکوم، خپل مړی دې په کې ښخ کړه.»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30350, '1 Chronicles 1:38', '1 Chronicles', 1, 38, 'د سعیر زامن دا وو: لوتان، شوبال، صبعون، عنه، دیشون، ایصر او دیشان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30351, '1 Chronicles 1:39', '1 Chronicles', 1, 39, 'د لوتان زامن حوري او هومام وو. تمناع د لوتان خور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30352, '1 Chronicles 1:40', '1 Chronicles', 1, 40, 'د شوبال زامن علوان، مناحت، عیبال، شفي او اونام نومېدل. ایه او عنه د صبعون زامن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30353, '1 Chronicles 1:41', '1 Chronicles', 1, 41, 'عنه د دیشون پلار ؤ او د حمران، اشبان، یتران او د کران نیکه ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
