(30379, '1 Kings 10:19', '1 Kings', 10, 19, 'تخت ته د ورختلو دپاره شپږ زینې وې او د تخت سر د شا له خوا ګرد ؤ. د تخت دواړو خواو ته بازوګان وو او د هر یو په خوا کې د زمري مجسمه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30380, '1 Kings 10:20', '1 Kings', 10, 20, 'په شپږو زینو باندې د دولسو زمریانو مجسمې وې، د هرې زینې هرې خواته یوه یوه مجسمه وه. په بلې هېڅ پاچاهۍ کې داسې تخت نه ؤ جوړ شوی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30381, 'Genesis 32:13', 'Genesis', 32, 13, 'هغه هلته شپه تېره کړه او هرڅه چې یې درلودل د هغو څخه یې د خپل ورور عیسو دپاره سوغات غوره کړ:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30382, 'Genesis 32:14', 'Genesis', 32, 14, 'دوه سوه وزې او شل سېرلي، دوه سوه مېږې او شل پسونه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30383, 'Genesis 32:15', 'Genesis', 32, 15, 'دېرش اوښې د هغو د بچیو سره، څلوېښت غواګانې او لس غویان، شل خرې او لس خره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30384, 'Ezekiel 4:10', 'Ezekiel', 4, 10, 'ستا خواړه به هره ورځ یوازې دوه سوه او دېرش ګرامه ډوډۍ وي او هغه به په ټاکلي وخت خورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30385, 'Ezekiel 4:11', 'Ezekiel', 4, 11, 'همدارنګه ته به په ټاکلي وخت یوازې دوه جامونه اوبه څښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30386, 'Genesis 49:29', 'Genesis', 49, 29, 'بیا یعقوب هغوی ته دغه وصیت وکړ: «زه به زر مړ شم او د خپلو نیکونو سره به یوځای شم. ما د خپلو نیکونو سره په هغې سمڅې کې ښخ کړئ چې د حیتي عفرون په پټي کې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30387, 'Genesis 49:30', 'Genesis', 49, 30, 'دا هغه سمڅه ده چې د مکفیلې په پټي کې ممري ته مخامخ د کنعان په خاوره کې پرته ده او ابراهیم هغه د پټي سره د عفرون څخه د هدیرې دپاره اخیستې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30388, '2 Kings 12:20', '2 Kings', 12, 20, 'د هغه د پاچاهۍ په پای کې د هغه ځینې درباریان د ده په وړاندې یاغي شول. یوآش یې د اورشلیم په ختیځ کې هغې لارې ته نژدې چې سلې ته تللې وه، د ملو په کور کې په قتل ورساوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30389, '2 Kings 12:21', '2 Kings', 12, 21, 'د هغو قاتلانو نومونه دا دي: د شمعت زوی یوزاکار او د شومیر زوی یهوزاباد. یوآش د داود د ښار په شاهي هدیره کې ښخ شو او د هغه زوی امصیا د هغه په ځای پاچا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30390, 'Song of Songs 7:1', 'Song of Songs', 7, 1, 'ستا پښې په څپلو کښې څومره ښُکلې ښکارينه، اے د شهزادګۍ لورې. ستا غونډى پتونونه د قيمتى کاڼو په شان دينه، لکه چې دا يو ماهر زرګر جوړ کړى وينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30391, 'Song of Songs 7:2', 'Song of Songs', 7, 2, 'ستا نوم د يوې پيالۍ په شان دېنه لکه چې د خوشبوداره ميو نه ډکه وينه. ستا پښې لکه د غنمو د ګېډۍ په شان دينه چې ګېرچاپېره ترې نه د لاله ګلونه راتاو شوى وينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30392, 'Song of Songs 7:3', 'Song of Songs', 7, 3, 'ستا سينې لکه د هوسو د جوړه بچو په شان دينه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30393, 'Song of Songs 7:4', 'Song of Songs', 7, 4, 'ستا غړۍ لکه د هاتى د غاښونو نه جوړه شوې مينارې په شان ښائسته ده نه. ستا سترګې د حسبون ښار د ځلېدونکو تالابونو په شان دينه، کوم تالابونه چې د دې ښار د بيت‌رابيم دروازې سره دينه. ستا پوزه د لبنان د برج په شان ښائسته ده نه چې د دمشق ښار ترې نه ښکارينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30394, 'Song of Songs 7:5', 'Song of Songs', 7, 5, 'ستا سر لکه د کرمل د غرۀ په شان اوچت دېنه، ستا د زلفو ښائست لکه د شاهى ګُلکارۍ په شان دېنه تر دې چې بادشاهان هم ستا د کمڅو د ولونو بنديوان دينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30395, 'Song of Songs 7:6', 'Song of Songs', 7, 6, 'اے محبوبې، تۀ څومره ښُکلې او حسينه ينه، تۀ څومره د خوشحالو نه ډکه ينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30396, 'Song of Songs 7:7', 'Song of Songs', 7, 7, 'ستا قد او قامت د کجورې د ونې په شان دېنه، او ستا سينې د مېوو د غونچو په شان دينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30397, 'Song of Songs 7:8', 'Song of Songs', 7, 8, 'ما وئيل زۀ به د کجورې ونې ته وخېژمه او کجورو ته به يې لاس وروړمه. ستا سينې دې د مېوو د غونچو په شان وينه، او ستا د خولې خوشبو دې لکه د سيوانو په شان وينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30398, 'Song of Songs 7:9', 'Song of Songs', 7, 9, 'او ستا شونډې د اعلىٰ ميو په شان دينه. نو دا مے دې زما د جانان په غاښونو او شونډو باندې په نرمۍ سره وبهيږينه. محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30399, 'Song of Songs 7:10', 'Song of Songs', 7, 10, 'زۀ د خپل جانان يمه، او د هغۀ زړۀ ما غواړينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30400, 'Song of Songs 7:11', 'Song of Songs', 7, 11, 'زما جانانه راشه، راځه چې بهر پټو ته لاړ شُو نه او هلته په کلى کښې شپه تېره کړو نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');